-- Water charges researched from each provider's official 2026/27 documents (docs/SPEC.md section 36; data/water_rates_research.csv).
-- Charging type always; a figure only where the source states it; verified only where read from the official document.
-- THRESHOLD is litres per day (an annual allowance divided by 365); VALUE_RATE is dollars per dollar of property value (water + wastewater).
insert into public.water_rates (prvdr, ta_code, valid_from, charging_type, fixed_pa, volumetric_pa, threshold_lpd, value_rate, value_basis, date_est, note, source_url, policy_url, website_url, verified, tariff)
values ('NPDC', '033', '2026-07-01', 'Fixed + volumetric (metered)', null, 3.15, null, null, null, '2026-11-26', 'Adopted Annual Plan 2026/27: metered water supply fixed $87.00 per connection; $3.15/m³ for the first 50,000 m³ a year, $3.17/m³ above; restricted supply $494 per m³/day. Wastewater fixed charge not stated in this document, so FIXED (water + wastewater) left blank.', 'https://www.npdc.govt.nz/media/sl2nqf3k/annual-plan-2026_27-adopted-at-council-meeting-25-june.pdf', 'https://www.npdc.govt.nz/media/sl2nqf3k/annual-plan-2026_27-adopted-at-council-meeting-25-june.pdf', 'https://www.npdc.govt.nz/home-and-property/water-wastewater-and-stormwater/water/water-meters/water-billing/', true, null)
on conflict (prvdr, (coalesce(ta_code, '')), valid_from) do update set charging_type = excluded.charging_type, fixed_pa = excluded.fixed_pa, volumetric_pa = excluded.volumetric_pa,
  threshold_lpd = excluded.threshold_lpd, value_rate = excluded.value_rate, value_basis = excluded.value_basis, date_est = excluded.date_est, note = excluded.note,
