values ('STRDC', '034', '2026-07-01', 'Fixed per connection (metered above allowance)', 1344.0, 2.77, null, null, null, '2026-11-26', 'Council agenda May 2026 (2026/27 rates): water supply $856 per connection (was $713), wastewater $488 (was $464). FIXED = $856 + $488. $2.77/m³ for supply in excess of the allowance (Stratford, Midhirst, Toko); allowance volume not stated here.', 'https://www.stratford.govt.nz/repository/libraries/id:2cvuccagl1cxbygm8445/hierarchy/SDC%20Agendas%20and%20Minutes/2026%20Agendas%20and%20Minutes/Ordinary/Agendas/2026%20-%20Agenda%20-%20Ordinary%20-%20May.PDF', 'https://www.stratford.govt.nz/repository/libraries/id:2cvuccagl1cxbygm8445/hierarchy/SDC%20Agendas%20and%20Minutes/2026%20Agendas%20and%20Minutes/Ordinary/Agendas/2026%20-%20Agenda%20-%20Ordinary%20-%20May.PDF', 'https://www.stratford.govt.nz/our-services/rates-and-property', true, null)
