values ('MNWDC', '039', '2026-07-01', 'Fixed per connection', 1649.0, null, null, null, null, '2026-11-26', 'Water services minutes 10 June 2026 (2026/27): water supply connected $500 per household (available $250, restricted $400); wastewater connected $1,149 per unit of use (available $574.50). FIXED = $500 + $1,149. Rural water schemes charged per unit allocated (Stanway/Halcombe $458, Waituna West $522, Ohakea $355.75, Kiwitea $281.75).', 'https://manawatudcweb.blob.core.windows.net/council-minutes/water-services/minutes/WS_10-06-2026.pdf', 'https://manawatudcweb.blob.core.windows.net/council-minutes/water-services/minutes/WS_10-06-2026.pdf', 'https://www.mdc.govt.nz/services/rates/water-rates', true, null)
