values ('WAIRDC', '029', '2026-07-01', 'Fixed per connection + per toilet (volumetric where metered)', 2396.5, 1.2, null, null, null, '2026-11-26', 'Rates Resolution 2026/27: Wairoa township water $1,277.50 per household connected (Mahanga $950.90, Tuai $1,042.70); sewerage $1,119.00 per toilet for the first five (Wairoa Ward). FIXED = water + one toilet. Water by meter $1.20/m³ (Wairoa township) applies only to metered properties.', 'https://www.wairoadc.govt.nz/assets/Document-Library/Policies/Rates/Rates-Resolution-2026-27-Final-.pdf', 'https://www.wairoadc.govt.nz/assets/Document-Library/Policies/Rates/Rates-Resolution-2026-27-Final-.pdf', 'https://www.wairoadc.govt.nz/services/properties-and-rates/rates/', true, null)
