values ('GISDC', '028', '2026-07-01', 'Fixed per connection', null, null, null, null, null, '2026-11-26', 'Disclosure of water charges July 2026: water connected $426.63 per year (available $213.31). Wastewater rate not stated in this document, so FIXED (water + wastewater) left blank.', 'https://www.gdc.govt.nz/__data/assets/pdf_file/0022/102685/Disclosure-of-Water-Charges-and-IFF-Levies-Information-July-2026.pdf', 'https://www.gdc.govt.nz/__data/assets/pdf_file/0022/102685/Disclosure-of-Water-Charges-and-IFF-Levies-Information-July-2026.pdf', 'https://www.gdc.govt.nz/services/rates/what-your-rates-pay-for', false, null)
