values ('CLDC', '072', '2026-07-01', 'Fixed + volumetric (metered above 366 m³/yr)', 2626.3, 4.65, 1003.0, null, null, '2026-11-26', 'Schedule of Fees and Charges 2026/27: urban water rate $1,700.70 and urban wastewater rate $925.60 (GST incl, stated as the basis of per-day charges); water used over 366 m³/year $4.65/m³ (THRESHOLD = 366 m³/yr = 1,003 L/day). FIXED = $1,700.70 + $925.60.', 'https://www.cluthadc.govt.nz/repository/libraries/id:2c0gik8bh17q9s5atec4/hierarchy/Documents/Schedule%20of%20Fees%20and%20Charges%202026-27.pdf', 'https://www.cluthadc.govt.nz/repository/libraries/id:2c0gik8bh17q9s5atec4/hierarchy/Documents/Schedule%20of%20Fees%20and%20Charges%202026-27.pdf', 'https://www.cluthadc.govt.nz/property-rates-and-building', true, null)
