values ('WSTDC', '057', '2026-07-01', 'Fixed per connection (volumetric for metered users)', 1466.0, null, null, null, null, '2026-11-26', 'Annual Plan 2026/27 rates: treated water $922 per connection (non-commercial; commercial $1,614; unconnected $461); untreated water $692; sewerage $544 connected ($272 unconnected). FIXED = $922 + $544. Metered water rates are volumetric for metered users; the per-m³ rate is not stated in this table.', 'https://westlanddc.govt.nz/media/luhhoe5o/annual-plan-2026-27-adopted.pdf', 'https://westlanddc.govt.nz/media/luhhoe5o/annual-plan-2026-27-adopted.pdf', 'https://westlanddc.govt.nz/property-rates-and-consents/water-services/', true, null)
