values ('GRYDC', '056', '2026-07-01', 'Fixed per connection (volumetric for metered users)', 2049.7, 1.1, null, null, null, '2026-11-26', 'Annual Plan 2026/27 funding impact statement: water supply $868.50 per household connected (Greymouth, Blackball, Dobson/Taylorville, Runanga; Kaiata $671.90, Stillwater $793.50); wastewater Greymouth $1,181.20 per household connected (other schemes $493.50 to $1,363.60). FIXED = $868.50 + $1,181.20 (Greymouth). Water by meter $1.10/m³ (all schemes) for metered users.', 'https://www.greydc.govt.nz/repository/libraries/id:2cvtsvtyv1cxbyz1k6uz/hierarchy/sitecollectiondocuments/Your%20Council/Council%20Publications/annual-plans/Final%20GDC%202026-2027%20Annual%20Plan.pdf', 'https://www.greydc.govt.nz/repository/libraries/id:2cvtsvtyv1cxbyz1k6uz/hierarchy/sitecollectiondocuments/Your%20Council/Council%20Publications/annual-plans/Final%20GDC%202026-2027%20Annual%20Plan.pdf', 'https://www.greydc.govt.nz/06your-home/e-property-and-rates', true, null)
