values ('PNCC', '040', '2026-07-01', 'Fixed per connection', 895.0, null, null, null, null, '2026-11-26', 'Rates booklet 2026: 2026/27 fixed targeted rates water $449 and wastewater $446 per connected property (non-residential metered water charged per m³). FIXED = $449 + $446. Central Districts Water responsible from July 2027.', 'https://www.pncc.govt.nz/files/assets/public/v/7/documents/rates/rates-booklet-2026.pdf', 'https://www.pncc.govt.nz/files/assets/public/v/7/documents/rates/rates-booklet-2026.pdf', 'https://www.pncc.govt.nz/Rates-Building-Property/Rates/Water-rates', true, null)
