values ('TIAKIWAI', '046', '2026-07-01', 'Fixed per household; metered: fixed + volumetric', 2014.0, 5.35, null, null, null, '2026-11-27', 'Hutt City residential 2026/27: water $1000 per household; wastewater $1014 per household (commercial: +$507 per extra toilets). Metered water: $1000 + $5.35/m³. Stormwater $41 per household + 0.00036509 per $ of capital value (excluded from FIXED). Volumetric applies to metered properties only. From the billing calculator''s embedded rates, checked against the Pricing Policy (1 July 2026). All figures appear in the Pricing Policy''s section for this city (checked 2026-11-27). Council page: Hutt City Council rates and water charges calculators 2026-27: https://www.huttcity.govt.nz/property-and-building/rates-and-valuations/rates-and-water-charges-calculators-202627.', 'https://qpulse.wellingtonwater.co.nz/QPulseDocumentService/Documents.svc/documents/active/attachment?number=POL_0416', 'https://qpulse.wellingtonwater.co.nz/QPulseDocumentService/Documents.svc/documents/active/attachment?number=POL_0416', 'https://www.tiakiwai.co.nz/billing/lower-hutt', true, '{"model":"tiakiwai-2026-27","source":"Tiaki Wai billing page calculator (data-rates), checked against the Tiaki Wai Pricing Policy 1 July 2026","rates":{"WCC":{"waterMeterFixed":359.21,"waterMeterRate":7.79,"waterResFixed":442,"waterResCVRate":0.00067964,"waterComFixed":1016.75,"waterComCVRate":0.00780448,"wwResFixed":203.89,"wwResCVRate":0.00063459,"wwComFixed":1134.2,"wwComCVRate":0.00273571,"swResFixed":67.39,"swResCVRate":0.00052241,"swComFixed":67.39,"swComCVRate":0.00076842},"HCC":{"waterMeterFixed":1000,"waterMeterRate":5.35,"waterSUIPFixed":1000,"wwSUIPFixed":1014,"wwPanFixedAdditional":507,"swResFixed":41,"swResCVRate":0.00036509,"swComFixed":41,"swComCVRateCentral":0.00112893,"swComCVRateSuburban":0.00102439},"PCC":{"waterMeterRate":4.63,"waterSUIPFixed":912.66,"wwPanFixed":1134.06,"swResFixed":25.1,"swResCVRate":0.00023971,"swComFixed":25.1,"swComCVRates":{"business_differential":0.00074309,"business_park":0.00047941,"motel":0.00034038,"shopping_plaza":0.00074309,"vacant_land":0.00107868}},"UHCC":{"waterMeterFixed":771,"waterMeterRateRes":3.37,"waterMeterRateCom":3.37,"waterNoMeterFixed":771,"waterNoMeterCVRate":0.0002348,"wwPanFixed":770.56,"swResFixed":28.44,"swResCVRate":0.00030947,"swComFixed":28.44,"swComCVRate":0.00043326}}}'::jsonb)
