values ('TIAKIWAI', '045', '2026-07-01', 'Fixed per household + capital value (water); metered: fixed + volumetric', 1541.56, 3.37, null, 0.0002348, 'capital value', '2026-11-27', 'Upper Hutt City residential 2026/27: water $771 per household + 0.0002348 per $ of capital value; wastewater $770.56 per toilet (one per home). Metered water: $771 + $3.37/m³. Stormwater $28.44 + 0.00030947 per $ of capital value (excluded from FIXED). Volumetric applies to metered properties only. From the billing calculator''s embedded rates, checked against the Pricing Policy (1 July 2026). All figures appear in the Pricing Policy''s section for this city (checked 2026-11-27). Council page: Upper Hutt City Council water services: https://www.upperhutt.govt.nz/Services/Water.', 'https://qpulse.wellingtonwater.co.nz/QPulseDocumentService/Documents.svc/documents/active/attachment?number=POL_0416', 'https://qpulse.wellingtonwater.co.nz/QPulseDocumentService/Documents.svc/documents/active/attachment?number=POL_0416', 'https://www.tiakiwai.co.nz/billing/upper-hutt', true, '{"model":"tiakiwai-2026-27","source":"Tiaki Wai billing page calculator (data-rates), checked against the Tiaki Wai Pricing Policy 1 July 2026","rates":{"WCC":{"waterMeterFixed":359.21,"waterMeterRate":7.79,"waterResFixed":442,"waterResCVRate":0.00067964,"waterComFixed":1016.75,"waterComCVRate":0.00780448,"wwResFixed":203.89,"wwResCVRate":0.00063459,"wwComFixed":1134.2,"wwComCVRate":0.00273571,"swResFixed":67.39,"swResCVRate":0.00052241,"swComFixed":67.39,"swComCVRate":0.00076842},"HCC":{"waterMeterFixed":1000,"waterMeterRate":5.35,"waterSUIPFixed":1000,"wwSUIPFixed":1014,"wwPanFixedAdditional":507,"swResFixed":41,"swResCVRate":0.00036509,"swComFixed":41,"swComCVRateCentral":0.00112893,"swComCVRateSuburban":0.00102439},"PCC":{"waterMeterRate":4.63,"waterSUIPFixed":912.66,"wwPanFixed":1134.06,"swResFixed":25.1,"swResCVRate":0.00023971,"swComFixed":25.1,"swComCVRates":{"business_differential":0.00074309,"business_park":0.000